const D = { ink: .9, scale: 1, energy: .6, density: .5, hue: 340, speed: 1, x: .5, y: .5, alpha: 1, style: 'duotone', act: 'press', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const inkP=cl(P.ink,0,1.6), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4);
const en=cl(P.energy,0,1)*(.5+.6*K.intensity);
const T=K.t*spd, H=md(P.hue,360);
const ax=cl(P.x,0,1), ay=cl(P.y,0,1);

S.bass=(S.bass||0)*.85+(A.bass||0)*.15;
S.tre=(S.tre||0)*.85+(A.treble||0)*.15;
const kick=Math.min(1, K.pulse*.5 + S.bass*.6);

// ---- misregistration: real-time drift at incommensurate rates (never re-phases)
let regAmp = u*0.0048*(0.55+en) * (1 + 0.55*kick*en);
if(act==='registration') regAmp*=3.4;
if(sty==='wet') regAmp*=2.1;
const regOf = i => [ regAmp*(Math.sin(T*0.19+i*2.1)+0.6*Math.sin(T*0.437+i*3.7)),
                     regAmp*(Math.cos(T*0.163+i*1.3)+0.6*Math.sin(T*0.311+i*5.1)) ];

// ---- separation artwork: each ink drum prints its OWN field ----
const NB = 3+Math.round(dens*4);
if(S.bSeed!==P.seed || S.bN!==NB){ S.bSeed=P.seed; S.bN=NB; S.b0=[];
  for(let i=0;i<NB;i++) S.b0.push({a:fr(i*3)*TAU, r:.10+fr(i*3+1)*.30, s:.11+fr(i*3+2)*.17,
    w1:.031+fr(i*7)*.05, w2:.017+fr(i*11)*.031, ph:fr(i*13)*TAU}); }
const BB=S.b0, bx=new Array(NB), by=new Array(NB), bs=new Array(NB);
for(let i=0;i<NB;i++){ const q=BB[i];
  bx[i]=ax + Math.cos(q.a+T*q.w1)*q.r*.92 + .06*Math.sin(T*q.w2*2.7+q.ph);
  by[i]=ay + Math.sin(q.a+T*q.w1*1.31)*q.r*.64 + .05*Math.cos(T*q.w2*1.9+q.ph);
  bs[i]=q.s*sc*(0.85+0.28*Math.sin(T*0.23+q.ph)); }
const covA=(x,y)=>{ let v=0; for(let i=0;i<NB;i++){ const dx=(x-bx[i])*1.5, dy=y-by[i];
  v+=Math.exp(-(dx*dx+dy*dy)/(bs[i]*bs[i]*1.5)); } return cl(v*1.2-0.06,0,1); };
const covB=(x,y)=>{
  const wx = x + .13*Math.sin(y*5.3/sc + T*.071) + .06*Math.sin(y*11.1/sc - T*.041);
  const wy = y + .10*Math.sin(x*4.1/sc - T*.053) + .05*Math.cos(x*8.7/sc + T*.089);
  let v=.5+.5*Math.sin((wx*7.4+wy*3.6)/sc + T*.11);
  v*= .58+.42*Math.sin((wy*4.2-wx*1.9)/sc - T*.067);
  return cl(Math.pow(cl(v,0,1),1.25),0,1); };
const covC=(x,y)=>{ let v=0,amp=.5,f=3.1/sc;
  for(let o=0;o<3;o++){ v+=amp*Math.sin(x*f*1.7+y*f*1.1+T*.05*(o+1)+o*2.3)*Math.cos(y*f*1.3-x*f*.7-T*.037*(o+1)); amp*=.5; f*=2.05; }
  return cl(.5+v*.95,0,1); };

// ---- ink drums per style ----
const negative=(sty==='negative'), wet=(sty==='wet');
let inks, paperH=42, paperS=7, paperB=91;
if(sty==='trio') inks=[{h:H,s:88,b:98,ang:15,f:0},{h:md(H+232,360),s:82,b:84,ang:75,f:1},{h:md(H+78,360),s:86,b:96,ang:45,f:2}];
else if(sty==='mono_key'){ paperB=93; inks=[{h:md(H+250,360),s:46,b:14,ang:22,f:3}]; }
else if(negative){ paperH=md(H+255,360); paperS=52; paperB=12; inks=[{h:H,s:78,b:100,ang:15,f:0},{h:md(H+225,360),s:60,b:100,ang:75,f:1}]; }
else inks=[{h:H,s:88,b:98,ang:15,f:0},{h:md(H+232,360),s:82,b:84,ang:75,f:1}];

// ---- paper stock (cached) ----
const pkey=W+'x'+Hh+'|'+sty+'|'+P.seed+'|'+Math.round(paperH);
if(!S.paper||S.pkey!==pkey){
  const g=(S.paper&&S.paper.width===W&&S.paper.height===Hh)?S.paper:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.noStroke(); g.background(paperH,paperS,paperB);
  g.strokeWeight(1);
  for(let i=0;i<520;i++){ const x=fr(i*17)*W, y=fr(i*17+1)*Hh, a=fr(i*17+2)*TAU, L=3+fr(i*17+3)*17;
    g.stroke(paperH, paperS+8, negative? paperB+18 : paperB-16, 8+fr(i*17+4)*14);
    g.line(x,y,x+Math.cos(a)*L,y+Math.sin(a)*L); }
  g.noStroke();
  for(let i=0;i<800;i++){ const x=fr(i*29)*W, y=fr(i*29+1)*Hh;
    g.fill(paperH, paperS+11, negative? paperB+22 : paperB-12, 5+fr(i*29+2)*11);
    g.circle(x,y,.8+fr(i*29+3)*2.2); }
  S.paper=g; S.pkey=pkey; }
image(S.paper,0,0);

// ---- screen the separations through rotated halftones, overprint ----
const dc=drawingContext, oldOp=dc.globalCompositeOperation;
noStroke();
dc.globalCompositeOperation = negative? 'lighter' : 'multiply';
let inkGain = inkP*(0.80+0.30*en)*al;
if(act==='run') inkGain *= 0.72+0.42*(0.5+0.5*Math.sin(T*0.047));
const cX=W/2, cY=Hh/2;
for(let n=0;n<inks.length;n++){
  const ik=inks[n];
  const ang=(ik.ang + (act==='registration'? Math.sin(T*0.09+n)*8 : 0))*TAU/360;
  const c1=Math.cos(ang), s1=Math.sin(ang);
  const bw=Math.abs(W*c1)+Math.abs(Hh*s1), bh=Math.abs(W*s1)+Math.abs(Hh*c1);
  let pitch=Math.max(u*0.012, u*0.026*sc);
  if((bw*bh)/(pitch*pitch)>2600) pitch=Math.sqrt(bw*bh/2600);
  const nx=Math.ceil(bw/pitch/2)+1, ny=Math.ceil(bh/pitch/2)+1;
  const off=regOf(n), sgn=(n%2)?-1:1;
  const fld = ik.f===0? covA : ik.f===1? covB : ik.f===2? covC : (x,y)=>Math.max(covA(x,y),covB(x,y)*0.92);
  const maxR=pitch*(wet?0.86:0.62);
  fill(ik.h, ik.s, ik.b, (negative?76:92)*al);
  for(let j=-ny;j<=ny;j++){
    const gy=j*pitch;
    for(let i=-nx;i<=nx;i++){
      const gx=i*pitch;
      const px=cX+gx*c1-gy*s1, py=cY+gx*s1+gy*c1;
      if(px<-pitch||px>W+pitch||py<-pitch||py>Hh+pitch) continue;
      const cov=cl(fld(px/W,py/Hh)*inkGain,0,1.2);
      if(cov<0.035) continue;
      circle(px+off[0]*sgn, py+off[1]*sgn, maxR*2*Math.sqrt(cov));
    }
  }
}

// ---- over-inked puddles (wet press) ----
if(wet){ dc.globalCompositeOperation='multiply';
  for(let i=0;i<7;i++){ const x=((fr(i*31)+0.13*Math.sin(T*0.05+i))%1)*W, y=((fr(i*31+1)+0.09*Math.cos(T*0.037+i*2))%1)*Hh;
    const ik=inks[i%inks.length]; fill(ik.h, 72, 68, 13*al); circle(x,y,u*(0.10+fr(i*31+2)*0.22)); } }

// ---- roller banding: uneven ink laydown scrolling down the sheet ----
dc.globalCompositeOperation = negative? 'lighter':'multiply';
const bandScroll=T*(act==='run'? 0.058 : 0.022);
for(let i=0;i<16;i++){
  const t=((i/16)+bandScroll)%1, y=t*Hh, h2=Hh*(0.02+fr(i*23)*0.055);
  const a=(negative?4.5:5.5)*(0.4+fr(i*23+1))*(0.5+en*0.8)*al;
  fill(negative? md(H+180,360): md(H+250,360), negative?42:30, negative?100:28, a);
  rect(0,y-h2/2,W,h2); }

// ---- squeegee sheen: slow diagonal pass, the second motion floor ----
dc.globalCompositeOperation='lighter';
const sang=(sty==='trio'?0.55:0.32)+0.10*Math.sin(T*0.031);
const ux=Math.cos(sang), uy=Math.sin(sang);
const L=Math.abs(W*ux)+Math.abs(Hh*uy)+1;
const cpos=(((T*0.028)%1)+1)%1*L, bwid=u*0.16;
const ox=W/2-(L/2-cpos)*ux, oy=Hh/2-(L/2-cpos)*uy;
const lg=dc.createLinearGradient(ox-bwid*ux,oy-bwid*uy,ox+bwid*ux,oy+bwid*uy);
lg.addColorStop(0,'rgba(255,255,255,0)');
lg.addColorStop(0.5,'rgba(255,255,255,'+(0.03+0.06*en*al).toFixed(3)+')');
lg.addColorStop(1,'rgba(255,255,255,0)');
dc.fillStyle=lg; dc.fillRect(0,0,W,Hh);

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.shadowBlur=0; noStroke();
